using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Reflection;
using System.Windows.Forms;
using System.Web.Script.Serialization;
class TaskbarDragTests {
 static int checks,failures;static void Check(bool ok,string text){checks++;if(!ok)failures++;Console.WriteLine((ok?"PASS ":"FAIL ")+text);}
 static void Mouse(TaskbarMonitor w,string method,int x,int y){typeof(Control).GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(w,new object[]{new MouseEventArgs(MouseButtons.Left,1,x,y,0)});Application.DoEvents();}
 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);using(var window=new TaskbarMonitor()){try{var cfg=new MonitorConfig{Taskbar=true};window.Update(new SystemSample{Utc=DateTime.UtcNow,Cpu=20,MemoryUsed=8,MemoryTotal=16},cfg);Application.DoEvents();Check(window.Visible&&cfg.TaskbarPositionLocked,"existing configuration defaults to locked position");int saved=0,opened=0;window.PositionChanged+=()=>saved++;window.OpenCard+=()=>opened++;var initial=window.Bounds;Mouse(window,"OnMouseDown",20,8);Mouse(window,"OnMouseMove",100,8);Mouse(window,"OnMouseUp",100,8);Check(window.Bounds==initial&&saved==0,"locked pointer movement cannot move or save window");Check(opened==1,"locked click still opens details");cfg.TaskbarPositionLocked=false;Mouse(window,"OnMouseDown",20,8);Mouse(window,"OnMouseMove",100,8);var during=window.Bounds;Check(during.Left>initial.Left,"unlocked mouse movement drags taskbar window");window.Position();Check(window.Bounds==during,"position timer cannot snap window back during drag");window.Update(new SystemSample{Utc=DateTime.UtcNow,Cpu=48},cfg);Check(window.Bounds==during,"live sampling does not interrupt dragging");Mouse(window,"OnMouseUp",20,8);Check(saved==1&&cfg.TaskbarOffset==during.Left-System.Windows.Forms.Screen.FromControl(window).Bounds.Left&&cfg.TaskbarSide=="left","drag release persists offset with stable left anchor");Check(opened==1,"drag release does not open details");Mouse(window,"OnMouseDown",20,8);Mouse(window,"OnMouseUp",20,8);Check(opened==2&&saved==1,"unlocked ordinary click still opens details");var item=window.ContextMenuStrip.Items.OfType<ToolStripMenuItem>().First(x=>x.Text=="锁定任务栏位置");item.PerformClick();Check(cfg.TaskbarPositionLocked&&saved==2,"context menu locks position and requests persistence");var roundtrip=new JavaScriptSerializer().Deserialize<MonitorConfig>(new JavaScriptSerializer().Serialize(cfg));Check(roundtrip.TaskbarPositionLocked&&roundtrip.TaskbarOffset==cfg.TaskbarOffset,"lock and dragged offset survive config serialization");cfg.Taskbar=false;window.Position();Check(!window.Visible,"hide immediately removes taskbar window");cfg.Taskbar=true;window.Position();Check(window.Visible,"show restores taskbar window");}catch(Exception e){failures++;Console.WriteLine(e);} }File.WriteAllText(Path.Combine(args[0],"taskbar-drag-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures,physical_mouse_verified=false}));return failures==0?0:1;}
}
